// Better Auth tables (core, organization plugin, API-key plugin).
//
// Generated by the Better Auth CLI from packages/auth/better-auth.config.ts, then edited by hand. Regenerate with
//   pnpm --filter @zamu/auth exec auth generate --config better-auth.config.ts --output ../db/src/schema/auth.ts --yes
// That overwrites these edits; review the diff and re-apply them:
// - ids default to uuidv7() (Postgres 18). invitation.id keeps gen_random_uuid(): the id is the secret in the link.
// - timestamps are timestamptz with defaultNow() everywhere.
// - user.kind is NOT NULL with a check constraint; session.active_organization_id and apikey.reference_id are uuid
//   foreign keys; member has a unique (organization_id, user_id).
// - user.theme (M2): the person's theme choice, with a check constraint. Better Auth does not read it.
// - user.last_workspace_id (0.10): the workspace the person used last, so `/` lands there after a sign-in.
//   Set null when that workspace is deleted. Better Auth does not read it.
// - API-key rate limiting defaults to off (the plugin is configured with rateLimit.enabled = false).
// - the generated v1 `relations()` blocks are replaced by defineRelations in ../relations.ts (Drizzle 1.0).
import { sql } from 'drizzle-orm';
import {
  type AnyPgColumn,
  boolean,
  check,
  index,
  integer,
  pgTable,
  text,
  timestamp,
  unique,
  uuid,
} from 'drizzle-orm/pg-core';

const id = () => uuid('id').default(sql`uuidv7()`).primaryKey();
const createdAt = () => timestamp('created_at', { withTimezone: true }).defaultNow().notNull();
const updatedAt = () =>
  timestamp('updated_at', { withTimezone: true })
    .defaultNow()
    .$onUpdate(() => new Date())
    .notNull();

export const user = pgTable(
  'user',
  {
    id: id(),
    name: text('name').notNull(),
    email: text('email').notNull().unique(),
    emailVerified: boolean('email_verified').default(false).notNull(),
    image: text('image'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    /** "person" signs in with a password; "agent" acts only through API keys. */
    kind: text('kind', { enum: ['person', 'agent'] })
      .default('person')
      .notNull(),
    /** For agents: the person accountable for what the agent does. */
    responsibleUserId: uuid('responsible_user_id').references((): AnyPgColumn => user.id, {
      onDelete: 'set null',
    }),
    /** Theme choice for people. Agents keep the default. */
    theme: text('theme', { enum: ['system', 'light', 'dark'] })
      .default('system')
      .notNull(),
    /** The workspace the person used last (0.10). Null until they open one, or once it is deleted. */
    lastWorkspaceId: uuid('last_workspace_id').references((): AnyPgColumn => organization.id, {
      onDelete: 'set null',
    }),
  },
  (table) => [
    check('user_kind_check', sql`${table.kind} in ('person', 'agent')`),
    check('user_theme_check', sql`${table.theme} in ('system', 'light', 'dark')`),
    index('user_responsibleUserId_idx').on(table.responsibleUserId),
    index('user_lastWorkspaceId_idx').on(table.lastWorkspaceId),
  ],
);

export const session = pgTable(
  'session',
  {
    id: id(),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    token: text('token').notNull().unique(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    ipAddress: text('ip_address'),
    userAgent: text('user_agent'),
    userId: uuid('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    activeOrganizationId: uuid('active_organization_id').references(() => organization.id, {
      onDelete: 'set null',
    }),
  },
  (table) => [index('session_userId_idx').on(table.userId)],
);

export const account = pgTable(
  'account',
  {
    id: id(),
    accountId: text('account_id').notNull(),
    providerId: text('provider_id').notNull(),
    userId: uuid('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    accessToken: text('access_token'),
    refreshToken: text('refresh_token'),
    idToken: text('id_token'),
    accessTokenExpiresAt: timestamp('access_token_expires_at', { withTimezone: true }),
    refreshTokenExpiresAt: timestamp('refresh_token_expires_at', { withTimezone: true }),
    scope: text('scope'),
    password: text('password'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [index('account_userId_idx').on(table.userId)],
);

export const verification = pgTable(
  'verification',
  {
    id: id(),
    identifier: text('identifier').notNull(),
    value: text('value').notNull(),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [index('verification_identifier_idx').on(table.identifier)],
);

/** A workspace. Its slug names it in web URLs (`/w/<slug>/`); old slugs live in workspace_slug_alias. */
export const organization = pgTable('organization', {
  id: id(),
  name: text('name').notNull(),
  slug: text('slug').notNull().unique(),
  logo: text('logo'),
  createdAt: createdAt(),
  metadata: text('metadata'),
});

/** Workspace membership. Roles: owner, admin, member. Agents are members too. */
export const member = pgTable(
  'member',
  {
    id: id(),
    organizationId: uuid('organization_id')
      .notNull()
      .references(() => organization.id, { onDelete: 'cascade' }),
    userId: uuid('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    role: text('role').default('member').notNull(),
    createdAt: createdAt(),
  },
  (table) => [
    unique('member_organizationId_userId_unique').on(table.organizationId, table.userId),
    index('member_userId_idx').on(table.userId),
  ],
);

export const invitation = pgTable(
  'invitation',
  {
    id: uuid('id').default(sql`gen_random_uuid()`).primaryKey(),
    organizationId: uuid('organization_id')
      .notNull()
      .references(() => organization.id, { onDelete: 'cascade' }),
    email: text('email').notNull(),
    role: text('role'),
    status: text('status').default('pending').notNull(),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    createdAt: createdAt(),
    inviterId: uuid('inviter_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
  },
  (table) => [
    index('invitation_organizationId_idx').on(table.organizationId),
    index('invitation_email_idx').on(table.email),
  ],
);

/** API keys. `key` holds a hash; scope lives in `metadata` (JSON text). */
export const apikey = pgTable(
  'apikey',
  {
    id: id(),
    configId: text('config_id').default('default').notNull(),
    name: text('name'),
    start: text('start'),
    /** Owning user (the plugin's `references` is "user"). */
    referenceId: uuid('reference_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    prefix: text('prefix'),
    key: text('key').notNull(),
    refillInterval: integer('refill_interval'),
    refillAmount: integer('refill_amount'),
    lastRefillAt: timestamp('last_refill_at', { withTimezone: true }),
    enabled: boolean('enabled').default(true),
    rateLimitEnabled: boolean('rate_limit_enabled').default(false),
    rateLimitTimeWindow: integer('rate_limit_time_window').default(86400000),
    rateLimitMax: integer('rate_limit_max').default(10),
    requestCount: integer('request_count').default(0),
    remaining: integer('remaining'),
    lastRequest: timestamp('last_request', { withTimezone: true }),
    expiresAt: timestamp('expires_at', { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    permissions: text('permissions'),
    metadata: text('metadata'),
  },
  (table) => [
    index('apikey_configId_idx').on(table.configId),
    index('apikey_referenceId_idx').on(table.referenceId),
    index('apikey_key_idx').on(table.key),
  ],
);
